from typing import Optional, Any  # noqa: F401
from taf.internal.aliasing import aliasing_scope
from taf.hw.mcs.mcs import MCS
from taf.hw.mcs.facade import MCSFacade


class mcs(object):

    """used for setting mcs phase and attenuation

    Under MCS devices are currently supported:
        - HBTE
            - PPSAM-64X16-2.3-3.8-90-0.5-360-1-A, PPSAM-64X16-2.3-5-90-0.5-360-1-S, PPSAM-64X16-2.3-5-90-0.5-360-1-A
        - TopYoung
            - MCS2338A2-64B16-A1, MCS2338A2-64B16-A4, MCS2338A2-64B16-B4, MCS2338A2-64B32-E6
        - HAOJIN
            - Radio_PSA_64X16-1024
    """

    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    lookup_handler, configured_mcs = aliasing_scope(name=__name__, lookup_arg='mcs_device', lookup_type=MCS)

    def __init__(self):
        self._facade = MCSFacade()

    def setup(self, alias=None, **kwargs):
        # type: (Optional[str], Any) -> MCS
        """
        init mcs instance, and startup mcs and create connection to mcs
        :param str alias: mcs alias name
        :param kwargs: device specific parameters:
            HBTE, TOPYOUNG:
            str vendor: mcs vender e.g HBTE, TOPYOUNG, HAOJIN
            str model: mcs model e.g MCS2338A2-64B16-A1, MCS2338A2-64B16-A4, MCS2338A2-64B16-B4, Radio_PSA_64X16-1024
            str version: mcs version
            str ip: mcs device ip address
            int port: mcs device port
            list access_ports: specified access ports for topyoung device operation.
            int in_num: input port number for HAOJIN device.
            int out_num: output port number for HAOJIN device.
            int horizontal_antenna_num_in_group: horizontal antenna num in group for HAOJIN device.
            int vertical_antenna_num_in_group: vertical antenna num in group for HAOJIN device.
        :return: mcs instance
        """
        configured_mcs = self._facade.setup(kwargs)
        self.configured_mcs.add(configured_mcs, alias)
        return configured_mcs

    @lookup_handler.implicit_lookup
    def teardown(self, mcs_device=None):
        # type: (Optional[str]) -> None
        """
        mcs teardown
        disconnect socket
        disconnect ssh with CTRL PC if device is TopYoung
        :param Optional[str] mcs_device: mcs alias name
        """
        self._facade.teardown(mcs_device)

    @lookup_handler.implicit_lookup
    def set_frequency(self, frequency, mcs_device=None, timeout=None,):
        # type: (float, Optional[str]) -> str
        """
        set mcs frequency value, not supported in HAOJIN MCS
        :param float frequency: frequency value
        :param Optional[str] mcs_device: mcs alias name
        :param Optional[int] timeout: set frequency operation timeout.
        :return: execute response
        """
        return self._facade.set_frequency(frequency, mcs_device, timeout=timeout)

    @lookup_handler.implicit_lookup
    def set_phases_according_to_angles(self, vertical_angle, horizontal_angle,
                                       vertical_distance, horizontal_distance,
                                       output_group_id=None, input_group_id=None,
                                       mcs_device=None):
        # type: (float, float, int, int, Optional[int], Optional[int], Optional[str]) -> str
        """
        set channel phases according to vertical, horizontal angles
        :param float vertical_angle: vertical angle
        :param float horizontal_angle: horizontal angle
        :param int vertical_distance: vertical matrix distance
        :param int horizontal_distance: horizontal matrix distance
        :param Optional[int] output_group_id: output group id.
                HBTE: output group id equal to output id.
                      e.g output_group_id = 1, mapping to B1
                TopYoung: output group id equal to output id.
                HAOJIN: output group id equal to output id.
        :param Optional[int] input_group_id: input group id.
                HBTE: if input group id is None, selected Amin-Amax for setting phase,
                      if input group id is a number, will calcuted real input ids,
                      e.g input_group_id = 1, mapping output_ids (A1, A2).
                TopYoung: input group id, A1/A2 input group id = 1
                HAOJIN: input group id, IN1/IN2 input group id = 0
        :param Optional[str] mcs_device: mcs alias name
        :return: execute response
        """
        return self._facade.set_phases_according_to_angles(vertical_angle, horizontal_angle,
                                                           vertical_distance, horizontal_distance,
                                                           output_group_id, input_group_id,
                                                           mcs_device)

    @lookup_handler.implicit_lookup
    def set_phase(self, phase, input_port, output_port, mcs_device=None):
        # type: (float, int, int, Optional[str]) -> str
        """
        set specified channel phase value
        :param float phase: set value
        :param int input_port: input port in channel
        :param int output_port: output port in channel
        :param Optional[str] mcs_device: mcs alias name
        :return: execute response
        """
        return self._facade.set_phase(phase, input_port, output_port, mcs_device)

    @lookup_handler.implicit_lookup
    def get_phase(self, input_port, output_port, mcs_device=None, **kwargs):
        # type: (int, int, Optional[str]) -> float
        """
        query specified channel phase value
        :param int input_port: input port channel
        :param int output_port: output port channel
        :param Optional[str] mcs_device: mcs alias name
        :param Optional[int] timeout: read output message timeout for haojin device.
        :return: phase value
        """
        return self._facade.get_phase(input_port, output_port, mcs_device, **kwargs)

    @lookup_handler.implicit_lookup
    def set_phases(self, phase, begin_input_port=1, end_input_port=64, output_port=1, mcs_device=None):
        # type: (float, Optional[int], Optional[int], Optional[int], Optional[str]) -> str
        """
        set specified channels' phase values
        :param float phase: set value
        :param Optional[int] begin_input_port: begin input port in channel
        :param Optional[int] end_input_port: end input port in channel
        :param Optional[int] output_port: output port in channel
        :param Optional[str] mcs_device: mcs alias name
        :return: execute response
        """
        return self._facade.set_phases(phase, begin_input_port, end_input_port, output_port, mcs_device)

    @lookup_handler.implicit_lookup
    def set_attenuation(self, attenuation, input_port, output_port, mcs_device=None):
        # type: (float, int,  int, Optional[str]) -> str
        """
        set specified channel attenuation value
        :param float attenuation: set value
        :param int input_port: input port in channel
        :param int output_port: output port in channel
        :param Optional[str] mcs_device: mcs alias name
        :return: execute response
        """
        return self._facade.set_attenuation(attenuation, input_port, output_port, mcs_device)

    @lookup_handler.implicit_lookup
    def get_attenuation(self, input_port, output_port, mcs_device=None, **kwargs):
        # type: (int, int, Optional[str]) -> float
        """
        query specified channel attenuation value
        :param int input_port: input port in channel
        :param int output_port: output port in channel
        :param Optional[str] mcs_device: mcs alias name
        :param Optional[int] timeout: read output message timeout for haojin device.
        :return: attenuation value
        """
        return self._facade.get_attenuation(input_port, output_port, mcs_device, **kwargs)

    @lookup_handler.implicit_lookup
    def set_odd_attenuations(self, attenuation,
                             begin_input_port=1, end_input_port=64,
                             output_port=1,
                             mcs_device=None):
        # type: (float, Optional[int], Optional[int], Optional[int], Optional[str]) -> str
        """
        set specified odd channel attenuation value
        :param float attenuation: set value
        :param Optional[int] begin_input_port: begin input port in channel
        :param Optional[int] end_input_port: end input port in channel
        :param Optional[int] output_port: output port in channel
        :param Optional[str] mcs_device: mcs alias name
        :return: execute response
        """
        return self._facade.set_odd_attenuations(attenuation,
                                                 begin_input_port, end_input_port,
                                                 output_port,
                                                 mcs_device)

    @lookup_handler.implicit_lookup
    def set_even_attenuations(self, attenuation,
                              begin_input_port=1, end_input_port=64,
                              output_port=1,
                              mcs_device=None):
        # type: (float, Optional[int], Optional[int], Optional[int], Optional[str]) -> str
        """
        set specified even channel attenuation value
        :param float attenuation: set value
        :param Optional[int] begin_input_port: begin input port in channel
        :param Optional[int] end_input_port: end input port in channel
        :param Optional[int] output_port: output port in channel
        :param Optional[str] mcs_device: mcs alias name
        :return: execute response
        """
        return self._facade.set_even_attenuations(attenuation,
                                                  begin_input_port, end_input_port,
                                                  output_port,
                                                  mcs_device)

    @lookup_handler.implicit_lookup
    def set_matrix_number(self, number, mcs_device=None):
        # type: (int, Optional[str]) -> str
        """
        The keyword is only available for Topyoung device.
        set matrix number for Topyoung device
        :param int number: matrix number, 64 or 1024
        :param Optional[str] mcs_device: mcs alias name
        :return: True or False indicating success or failure
        """
        return self._facade.set_matrix_number(number, mcs_device)

    @lookup_handler.implicit_lookup
    def read_matrix_number(self, mcs_device=None):
        # type: (Optional[str]) -> int
        """
        The keyword is only available for Topyoung device.
        read matrix number for Topyoung device
        :param Optional[str] mcs_device: mcs alias name
        :return: matrix number
        """
        return self._facade.read_matrix_number(mcs_device)

    @lookup_handler.implicit_lookup
    def set_position(self, matrix_positions, mcs_device=None):
        # type: (int, dict, Optional[str]) -> str
        """
        set position for Topyoung device
        :param dict matrix_positions:
            e.g {1: [("A1", 1, 1), ("A2", 2, 2), ("A3", 1, 3)],
                 2: [("A4", 1, 1), ("A5", 2, 2), ("A6", 1, 3)]
            dict key is matrix id, 1 or 2
            dict value is positions, like List[Tuple[int, int, int]] positions: list of positions to set
                e.g [("A1", 1, 1), ("A1", 2, 2), ("A1", 1, 3)]
                where each tuple is (A port, row number, column number)
        :param Optional[str] mcs_device: mcs alias name
        :return: True or False indicating success or failure
        """
        return self._facade.set_position(matrix_positions, mcs_device)

    @lookup_handler.implicit_lookup
    def read_position(self, matrix_id, mcs_device=None):
        # type: (int, Optional[str]) -> List[Tuple[int, int, int]]
        """
        read position for Topyoung device
        :param int matrix_id: matrix id, 1 or 2
        :param Optional[str] mcs_device: mcs alias name
        :return: list of positions
            e.g [("A1", 1, 1), ("A1", 2, 2), ("A1", 1, 3)]
            where each tuple is (A port, row number, column number)
        """
        return self._facade.read_position(matrix_id, mcs_device)

    @lookup_handler.implicit_lookup
    def set_aedis(self, matrix_id,
                  horizontal_d_value, vertical_d_value,
                  ul_horizontal_d_value=None, ul_vertical_d_value=None,
                  mcs_device=None):
        # type: (int, float, float, float, float, Optional[str]) -> str
        """
        set aedis for Topyoung device
        :param int matrix_id: matrix id, 1 or 2
        :param float horizontal_d_value: horizontal distance value
        :param float vertical_d_value: vertical distance value
        :param float ul_horizontal_d_value: uplink horizontal distance value
        :param float ul_vertical_d_value: uplink vertical distance value
        :param Optional[str] mcs_device: mcs alias name
        :return: True or False indicating success or failure
        """
        return self._facade.set_aedis(matrix_id, horizontal_d_value, vertical_d_value,
                                      ul_horizontal_d_value, ul_vertical_d_value,
                                      mcs_device)

    @lookup_handler.implicit_lookup
    def read_aedis(self, mcs_device=None):
        # type: (Optional[str]) -> str
        """
        read aedis for Topyoung device
        :param Optional[str] mcs_device: mcs alias name
        :return: aedis value
        """
        return self._facade.read_aedis(mcs_device)

    @lookup_handler.implicit_lookup
    def set_beam(self, port, matrix_id,
                 horizontal_beam_angle, vertical_beam_angle,
                 even_attenuation_enable=False, event_attenuation_value=0,
                 odd_attenuation_enable=False, odd_attenuation_value=0,
                 mcs_device=None):
        # type: (str, int, float, float, int, int, int, int, Optional[str]) -> bool
        """
        set beam parameters only available for Topyoung device.
        :param str port: B port number, e.g "B1", "B2"
        :param int matrix_id: matrix id, 1 or 2
        :param float horizontal_beam_angle: horizontal beam angle
        :param float vertical_beam_angle: vertical beam angle
        :param bool even_attenuation_enable: enable even channel attenuation, False disabled, True enabled,
                                             default is False.
        :param float event_attenuation_value: even channel attenuation value
        :param bool odd_attenuation_enable: enable odd channel attenuation, False disabled, True enabled
                                            default is False.
        :param float odd_attenuation_value: odd channel attenuation value
        :param Optional[str] mcs_device: mcs alias name
        :return: True or False indicating success or failure
        """
        return self._facade.set_beam(port, matrix_id,
                                     horizontal_beam_angle, vertical_beam_angle,
                                     even_attenuation_enable, event_attenuation_value,
                                     odd_attenuation_enable, odd_attenuation_value,
                                     mcs_device)
